const reviews=[{"id": 1, "product": "핑크 큐피드 케이스", "title": "", "caption": ""}, {"id": 2, "product": "네잎클로버 케이스", "title": "", "caption": ""}, {"id": 3, "product": "네잎클로버 케이스", "title": "", "caption": ""}, {"id": 4, "product": "네잎클로버 케이스", "title": "드디어 찾았다 내 평생 폰케이스 진.익.규 🍀", "caption": ""}, {"id": 5, "product": "익규와 함께한 순간", "title": "", "caption": ""}, {"id": 6, "product": "네잎클로버 케이스", "title": "", "caption": ""}, {"id": 7, "product": "블루리본 · 네잎클로버", "title": "", "caption": ""}, {"id": 8, "product": "핑크 큐피드 케이스", "title": "익규 폰케이스 졸귀", "caption": ""}, {"id": 9, "product": "핑크 큐피드 케이스", "title": "", "caption": ""}, {"id": 10, "product": "화들짝 케이스", "title": "", "caption": ""}];
function reviewCard(r){return `<button class="review-card" data-review="${r.id}" aria-label="${r.product} 고객 사진 크게 보기"><img src="assets/reviews/review-${r.id}.jpg" alt="${r.product} 고객 제공 사진 ${r.id}" loading="lazy"><div class="review-copy"><span>제품명 : ${r.product}</span>${r.title?`<h3>${r.title}</h3>`:''}</div></button>`}
const preview=document.querySelector('#review-preview');if(preview)preview.innerHTML=[reviews[3],reviews[7],reviews[6]].map(reviewCard).join('');
const gallery=document.querySelector('#review-gallery');if(gallery)gallery.innerHTML=reviews.map(reviewCard).join('');
const lightbox=document.createElement('dialog');lightbox.className='photo-lightbox';lightbox.innerHTML='<button class="lightbox-close" aria-label="리뷰 사진 닫기">×</button><img alt=""><p></p>';document.body.append(lightbox);
document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const r=reviews.find(r=>r.id===+b.dataset.review);lightbox.querySelector('img').src=`assets/reviews/review-${r.id}.jpg`;lightbox.querySelector('img').alt=r.product+' 고객 제공 사진';lightbox.querySelector('p').textContent=r.title||r.product;lightbox.showModal()});
lightbox.querySelector('button').onclick=()=>lightbox.close();lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
